cap_user_header_t h = { 0 };
cap_user_data_t d[2]; // V3 supports 64 capability bits

// 1. Setup Header (Version and PID)
h.__version = _LINUX_CAPABILITY_VERSION_3;
h.pid = 0; // Target self

// 2. Define Capability Sets (data[0] for first 32 caps)
d[0].effective = 1 << CAP_CHOWN;
d[0].permitted = d[0].effective;
d[0].inheritable = 0;

// Note: Clear d[1] if using V3 and not setting high bits
d[1].effective = 0;
d[1].permitted = 0;
d[1].inheritable = 0;

// 3. Execute System Call
int result = capset(&h, d);
// Use cap_set_proc(3) for portable code.
